from pathlib import Path

path = Path("main.ino")
text = path.read_text(encoding="utf-8")

replacements = [
    ('#include <Arduino.h>\n#include <Wire.h>\n#include <esp_arduino_version.h>\n', '#include <Arduino.h>\n#include <Wire.h>\n#include <Preferences.h>\n#include <esp_arduino_version.h>\n', "include block"),
    ('namespace ScheduleLayout\n{\n    constexpr int ButtonTop = 830;\n', 'namespace TimeSync\n{\n    constexpr uint32_t IntervalMinutes = 12 * 60;\n    constexpr unsigned long CheckIntervalMilliseconds = 5UL * 60UL * 1000UL;\n\n    constexpr const char *PreferencesNamespace = "eventbadge";\n    constexpr const char *LastSyncKey = "lastNtp";\n}\n\nnamespace ScheduleLayout\n{\n    constexpr int ButtonTop = 830;\n', "ScheduleLayout location"),
    ('WifiConfig wifiConfig;\nWifiConnection wifiConnection;\n\nbool displayReady = false;\nbool touchReady = false;\n', 'WifiConfig wifiConfig;\nWifiConnection wifiConnection;\nPreferences preferences;\n\nbool displayReady = false;\nbool touchReady = false;\nbool wifiConfigReady = false;\nbool preferencesReady = false;\n\nuint32_t lastSuccessfulSyncMinutes = 0;\nunsigned long lastTimeSyncCheck = 0;\n', "global WiFi block"),
    ('bool HasNextSchedulePage();\nbool HasPreviousSchedulePage();\n\nbool IsMenuSelection(\n', 'bool HasNextSchedulePage();\nbool HasPreviousSchedulePage();\n\nvoid CheckTimeSync(bool forceCheck);\nbool ShouldSyncTime();\nuint32_t RtcMinutesSince2000();\nbool IsLeapYear(int year);\nint DaysInMonth(int year, int month);\n\nbool IsMenuSelection(\n', "function declaration block"),
    ('    badgeConfig.LoadDefaults();\n    storage.LoadBadge(badgeConfig);\n\n    // Temporary NTP/RTC synchronization test.\n    // For this proof step, synchronize on every boot.\n    if (wifiConfig.LoadFromSd())\n    {\n        wifiConnection.SyncRtc(\n            wifiConfig,\n            rtcClock,\n            15000,\n            10000);\n    }\n\n    if (!display.Begin())\n', '    badgeConfig.LoadDefaults();\n    storage.LoadBadge(badgeConfig);\n\n    preferencesReady =\n        preferences.begin(\n            TimeSync::PreferencesNamespace,\n            false);\n\n    if (preferencesReady)\n    {\n        lastSuccessfulSyncMinutes =\n            preferences.getUInt(\n                TimeSync::LastSyncKey,\n                0);\n    }\n    else\n    {\n        Serial.println("NTP: unable to open Preferences storage.");\n    }\n\n    wifiConfigReady =\n        wifiConfig.LoadFromSd();\n\n    CheckTimeSync(true);\n\n    if (!display.Begin())\n', "startup NTP block"),
    ('    if (currentScreen == Screen::Menu &&\n        millis() - menuLastActivity >=\n            MenuLayout::TimeoutMilliseconds)\n    {\n        Serial.println("Menu timeout. Returning to badge.");\n        ShowBadge();\n    }\n\n    delay(20);\n}\n', '    if (currentScreen == Screen::Menu &&\n        millis() - menuLastActivity >=\n            MenuLayout::TimeoutMilliseconds)\n    {\n        Serial.println("Menu timeout. Returning to badge.");\n        ShowBadge();\n    }\n\n    if (millis() - lastTimeSyncCheck >=\n        TimeSync::CheckIntervalMilliseconds)\n    {\n        CheckTimeSync(false);\n    }\n\n    delay(20);\n}\n', "loop timeout block"),
]

for old, new, label in replacements:
    if old not in text:
        raise SystemExit("STOP: " + label + " does not match the expected pushed baseline.")
    text = text.replace(old, new, 1)

marker = 'bool IsMenuSelection(\n    const TouchPoint &point,\n    int top,\n    int bottom)\n'
if marker not in text:
    raise SystemExit("STOP: IsMenuSelection location was not found.")

text = text.replace(marker, 'void CheckTimeSync(\n    bool forceCheck)\n{\n    if (!forceCheck &&\n        millis() - lastTimeSyncCheck <\n            TimeSync::CheckIntervalMilliseconds)\n    {\n        return;\n    }\n\n    lastTimeSyncCheck = millis();\n\n    rtcClock.Read();\n\n    if (!ShouldSyncTime())\n    {\n        if (rtcClock.IsValid() &&\n            lastSuccessfulSyncMinutes != 0)\n        {\n            uint32_t nowMinutes =\n                RtcMinutesSince2000();\n\n            uint32_t ageMinutes =\n                nowMinutes -\n                lastSuccessfulSyncMinutes;\n\n            Serial.printf(\n                "NTP: sync not required. Last sync was %lu minutes ago.\\n",\n                static_cast<unsigned long>(ageMinutes));\n        }\n\n        return;\n    }\n\n    if (!wifiConfigReady)\n    {\n        Serial.println(\n            "NTP: synchronization is due, but WiFi configuration is unavailable.");\n        return;\n    }\n\n    Serial.println("NTP: 12-hour synchronization is due.");\n\n    bool synchronized =\n        wifiConnection.SyncRtc(\n            wifiConfig,\n            rtcClock,\n            15000,\n            10000);\n\n    if (!synchronized)\n    {\n        Serial.println(\n            "NTP: synchronization failed. Existing RTC time retained.");\n        return;\n    }\n\n    if (!rtcClock.IsValid())\n    {\n        Serial.println(\n            "NTP: synchronization completed but RTC is not valid.");\n        return;\n    }\n\n    lastSuccessfulSyncMinutes =\n        RtcMinutesSince2000();\n\n    if (preferencesReady)\n    {\n        size_t written =\n            preferences.putUInt(\n                TimeSync::LastSyncKey,\n                lastSuccessfulSyncMinutes);\n\n        if (written == 0)\n        {\n            Serial.println(\n                "NTP: warning - unable to save last sync time.");\n        }\n    }\n\n    Serial.printf(\n        "NTP: next synchronization due in %lu minutes.\\n",\n        static_cast<unsigned long>(\n            TimeSync::IntervalMinutes));\n}\n\nbool ShouldSyncTime()\n{\n    if (!rtcClock.IsValid())\n    {\n        Serial.println(\n            "NTP: RTC is invalid. Synchronization required.");\n        return true;\n    }\n\n    if (lastSuccessfulSyncMinutes == 0)\n    {\n        Serial.println(\n            "NTP: no previous successful sync is stored.");\n        return true;\n    }\n\n    uint32_t nowMinutes =\n        RtcMinutesSince2000();\n\n    if (nowMinutes < lastSuccessfulSyncMinutes)\n    {\n        Serial.println(\n            "NTP: RTC is earlier than the stored sync time.");\n        return true;\n    }\n\n    return\n        nowMinutes -\n        lastSuccessfulSyncMinutes >=\n        TimeSync::IntervalMinutes;\n}\n\nuint32_t RtcMinutesSince2000()\n{\n    if (!rtcClock.IsValid())\n    {\n        return 0;\n    }\n\n    uint32_t days = 0;\n\n    for (int year = 2000;\n         year < rtcClock.Year();\n         year++)\n    {\n        days +=\n            IsLeapYear(year)\n            ? 366\n            : 365;\n    }\n\n    for (int month = 1;\n         month < rtcClock.Month();\n         month++)\n    {\n        days +=\n            DaysInMonth(\n                rtcClock.Year(),\n                month);\n    }\n\n    days +=\n        rtcClock.Day() - 1;\n\n    return\n        days * 24UL * 60UL +\n        rtcClock.Hour() * 60UL +\n        rtcClock.Minute();\n}\n\nbool IsLeapYear(\n    int year)\n{\n    if ((year % 400) == 0)\n    {\n        return true;\n    }\n\n    if ((year % 100) == 0)\n    {\n        return false;\n    }\n\n    return\n        (year % 4) == 0;\n}\n\nint DaysInMonth(\n    int year,\n    int month)\n{\n    if (month == 2)\n    {\n        return\n            IsLeapYear(year)\n            ? 29\n            : 28;\n    }\n\n    if (month == 4 ||\n        month == 6 ||\n        month == 9 ||\n        month == 11)\n    {\n        return 30;\n    }\n\n    return 31;\n}\n\n\n' + marker, 1)

path.write_text(text, encoding="utf-8")
print("12-hour NTP synchronization patch applied.")
